package org.transittr;
import android.content.*;import java.io.*;import java.util.*;import java.security.*;import org.json.*;
/** Versioned, bounded backup; imports validate all data before merging. */
public final class QueryBackup {
 private static final int LIMIT=524288,MAX_STARS=200;
 private static String catalogFingerprint(Context c)throws IOException{try{MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] b=new byte[4096];for(String name:new String[]{"catalog-stream-0.dbz","catalog-stream-1.dbz","catalog-stream-2.dbz","catalog-stream-6.dbz"}){digest.update(name.getBytes("UTF-8"));InputStream in=c.getAssets().open(name);try{int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}finally{in.close();}}StringBuilder out=new StringBuilder();for(byte value:digest.digest()){int n=value&255;if(n<16)out.append('0');out.append(Integer.toHexString(n));}return out.toString();}catch(NoSuchAlgorithmException e){throw new IOException("Katalog doğrulanamadı");}}
 private static String value(JSONObject x,String key){return x.optString(key,"").trim();}
 private static String key(int city,String stop,String line,String direction){return city+":"+stop+":"+line.toUpperCase(Locale.US)+":"+direction;}
 private static String starKey(JSONObject x)throws JSONException,IOException{int kind=x.getInt("kind"),id=x.getInt("id");if(kind!=0&&kind!=1)throw new IOException("Geçersiz katalog kaydı");return "fav:"+kind+":"+id;}
 private static void validateNetwork(JSONObject record,int kind)throws JSONException,IOException{if(!record.has("network"))return;JSONObject n=record.getJSONObject("network");if(n.toString().length()>2048||!NetworkCatalog.city(n.optInt("city",-1))||n.optBoolean("stop",false)!=(kind==1))throw new IOException("Geçersiz katalog bilgisi");JSONObject item=n.getJSONObject("item");if(item.toString().length()>1600||item.optString("name","").length()>160||item.optString("stopId","").length()>64||item.optString("displayRouteCode","").length()>64||item.optString("routeCode","").length()>64)throw new IOException("Geçersiz katalog bilgisi");}
 public static byte[] exportBytes(Context c)throws IOException{try{JSONObject root=new JSONObject();root.put("format","transit-tr-query-backup");root.put("version",1);JSONArray f=new JSONArray();for(WidgetFavorites.Entry e:WidgetFavorites.all(c)){JSONObject x=new JSONObject();x.put("city",e.city);x.put("stop",e.stop);x.put("line",e.line);x.put("direction",e.direction);x.put("label",e.label);f.put(x);}JSONArray h=new JSONArray();for(RecentQueries.Entry e:RecentQueries.all(c)){JSONObject x=new JSONObject();x.put("city",e.city);x.put("stop",e.stop);x.put("line",e.line);x.put("direction",e.direction);h.put(x);}SharedPreferences prefs=c.getSharedPreferences("MainActivity",0);ArrayList<String> keys=new ArrayList<String>();for(Map.Entry<String,?> entry:prefs.getAll().entrySet())if(entry.getKey().matches("fav:[01]:-?[0-9]{1,10}")&&Boolean.TRUE.equals(entry.getValue()))keys.add(entry.getKey());Collections.sort(keys);if(keys.size()>MAX_STARS)throw new IOException("Katalog favorileri sınırı aşıyor");JSONArray stars=new JSONArray();for(String k:keys){String[] parts=k.split(":");int kind=Integer.parseInt(parts[1]),id=Integer.parseInt(parts[2]);JSONObject item=new JSONObject();item.put("kind",kind);item.put("id",id);String data=prefs.getString("network-item:"+kind+":"+id,"");if(data.length()>0){if(data.length()>2048)throw new IOException("Katalog bilgisi çok büyük");item.put("network",new JSONObject(data));validateNetwork(item,kind);}stars.put(item);}root.put("favorites",f);root.put("recent",h);root.put("catalog_fingerprint",stars.length()==0?"":catalogFingerprint(c));root.put("catalog_favorites",stars);byte[] bytes=root.toString(2).getBytes("UTF-8");if(bytes.length>LIMIT)throw new IOException("Yedek sınırı aşıyor");return bytes;}catch(JSONException e){throw new IOException("Yedek oluşturulamadı");}catch(NumberFormatException e){throw new IOException("Katalog anahtarı geçersiz");}}
 public static int importStream(Context c,InputStream input)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=input.read(b))!=-1){if(out.size()+n>LIMIT)throw new IOException("Yedek dosyası çok büyük");out.write(b,0,n);}try{JSONObject root=new JSONObject(new String(out.toByteArray(),"UTF-8"));if(!"transit-tr-query-backup".equals(root.optString("format"))||root.optInt("version",-1)!=1)throw new IOException("Desteklenmeyen yedek biçimi");JSONArray f=root.getJSONArray("favorites"),h=root.getJSONArray("recent"),stars=root.optJSONArray("catalog_favorites");if(stars==null)stars=new JSONArray();if(f.length()>12||h.length()>8||stars.length()>MAX_STARS)throw new IOException("Yedek kayıt sınırını aşıyor");if(stars.length()>0&&!catalogFingerprint(c).equals(root.optString("catalog_fingerprint","")))throw new IOException("Katalog verisi farklı; yıldızları yanlış eşleştirmemek için yedek aktarılmadı");HashSet<String> keys=new HashSet<String>();for(WidgetFavorites.Entry e:WidgetFavorites.all(c))keys.add(key(e.city,e.stop,e.line,e.direction));int original=keys.size();for(int i=0;i<f.length();i++){JSONObject x=f.getJSONObject(i);int city=x.optInt("city",-1);String stop=value(x,"stop"),line=value(x,"line"),direction=value(x,"direction"),label=x.optString("label","");if(!WidgetFavorites.valid(city,stop,line,direction)||label.length()>60)throw new IOException("Yedekte geçersiz favori var");keys.add(key(city,stop,line,direction));}if(keys.size()>12)throw new IOException("Favoriler 12 kaydı aşacağı için içe aktarılmadı");for(int i=0;i<h.length();i++){JSONObject x=h.getJSONObject(i);int city=x.optInt("city",-1);String stop=value(x,"stop"),line=value(x,"line"),direction=value(x,"direction");if(!CityRegistry.valid(city)||!stop.matches(city==0?"[0-9]{5}":"[0-9]{1,8}")||!line.matches("[A-Za-z0-9ÇĞİÖŞÜçğıöşü-]{0,16}")||!(direction.equals("")||city==1&&(direction.equals("G")||direction.equals("D"))))throw new IOException("Yedekte geçersiz geçmiş kaydı var");}SharedPreferences catalog=c.getSharedPreferences("MainActivity",0);HashSet<String> catalogKeys=new HashSet<String>();for(Map.Entry<String,?> e:catalog.getAll().entrySet())if(e.getKey().matches("fav:[01]:-?[0-9]{1,10}")&&Boolean.TRUE.equals(e.getValue()))catalogKeys.add(e.getKey());for(int i=0;i<stars.length();i++){JSONObject star=stars.getJSONObject(i);String k=starKey(star);validateNetwork(star,star.getInt("kind"));catalogKeys.add(k);}if(catalogKeys.size()>MAX_STARS)throw new IOException("Katalog favorileri 200 kaydı aşacağı için içe aktarılmadı");HashSet<String> existing=new HashSet<String>();for(WidgetFavorites.Entry e:WidgetFavorites.all(c))existing.add(key(e.city,e.stop,e.line,e.direction));for(int i=0;i<f.length();i++){JSONObject x=f.getJSONObject(i);int city=x.getInt("city");String stop=value(x,"stop"),line=value(x,"line"),direction=value(x,"direction"),k=key(city,stop,line,direction);if(existing.add(k))WidgetFavorites.add(c,city,stop,line,direction,x.optString("label",""));}SharedPreferences.Editor edit=catalog.edit();for(int i=0;i<stars.length();i++){JSONObject star=stars.getJSONObject(i);String k=starKey(star);if(!catalog.getBoolean(k,false)){edit.putBoolean(k,true);if(star.has("network"))edit.putString("network-item:"+star.getInt("kind")+":"+star.getInt("id"),star.getJSONObject("network").toString());}}if(!edit.commit())throw new IOException("Katalog favorileri kaydedilemedi");for(int i=h.length()-1;i>=0;i--){JSONObject x=h.getJSONObject(i);RecentQueries.record(c,x.getInt("city"),value(x,"stop"),value(x,"line"),value(x,"direction"));}return keys.size()-original;}catch(JSONException e){throw new IOException("Yedek dosyası okunamadı");}}
}
